                .build()
                .postForObject("/decompress", compressed, Tensor.class);
    }
}

// Enum of supported strategies
public enum StrategyType { LOW_RANK, NONE }

// Factory for strategy resolution
public class CompressionFactory {
    public static CompressionStrategy create(StrategyType type, int rank) {
        return switch (type) {
