### 4. Python Low‑Rank Worker

```python
from flask import Flask, request, jsonify
import numpy as np
from scipy.linalg import svd

app = Flask(__name__)

@app.route('/compress', methods=['POST'])
def compress():
    data = request.json
    kv = np.array(data['values'])
    rank = int(request.args.get('rank', 50))
    u, s, vt = svd(kv, full_matrices=False)
    compressed = {
        'u': u[:, :rank].tolist(),
        's': s[:rank].tolist(),
        'vt': vt[:rank, :].tolist()
    }
    return jsonify(compressed)

@app.route('/decompress', methods=['POST'])
def decompress():
    data = request.json
    u = np.array(data['u'])
    s = np.array(data['s'])
    vt = np.array(data['vt'])
    kv = u @ np.diag(s) @ vt
    return jsonify({'values': kv.tolist()})
```

